func storePic9v99(v decimal.Decimal) decimal.Decimal {
	v = truncateDecimal(v, 2)
	// keep low-order 7 digits (5 integer + 2 decimal) = value mod 100000.00 ?
	// PIC 9(5)V99 max 99999.99 => modulus 100000.00
	mod := decimal.NewFromInt(10000000).Shift(-2) // 100000.00
	// for positive values, low-order digits = v mod mod
	// decimal.Mod not suitable for exact; use integer representation
	// Convert to cents: v *100 truncated
	cents := v.Shift(2).Truncate(0)
	// modulus in cents = 10000000
	m := int64(10000000)
	ci := cents.IntPart()
	// handle positive only (program only uses positive)
	ci = ci % m
	if ci < 0 {
		ci += m
	}
	return decimal.New(ci, -2)
}

func storePic9v99_8(v decimal.Decimal) decimal.Decimal {
	v = truncateDecimal(v, 2)
	mod := decimal.NewFromInt(1000000000).Shift(-2) // 100000000.00 ? 9(8)V99 => 100000000.00
	cents := v.Shift(2).Truncate(0)
	m := int64(10000000000) // 10 digits cents
	ci := cents.IntPart()
	ci = ci % m
	if ci < 0 {
		ci += m
	}
	return decimal.New(ci, -2)
}

func formatEdited(v decimal.Decimal, pic string) string {
	// pic like "ZZ,ZZ9.99" or "ZZ,ZZZ,ZZ9.99"
	// Determine scale = number of '9' after '.'
	scale := int32(0)
	intPartPic := pic
	if idx := strings.Index(pic, "."); idx != -1 {
		intPartPic = pic[:idx]
		decPart := pic[idx+1:]
		for _, ch := range decPart {
			if ch == '9' || ch == 'Z' {
				scale++
			}
		}
	}
	// count integer digit positions (Z and 9)
	intDigits := 0
	for _, ch := range intPartPic {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	// Ensure v is truncated to scale (caller already)
	// For formatting, we need absolute value (no sign in this program)
	if v.IsNegative() {
		v = v.Neg()
	}
	v = v.Truncate(scale)
	// Get integer part and decimal part
	// Use string representation
	// integer part
	intPart := v.IntPart() // truncates toward zero
	if intPart < 0 {
		intPart = -intPart
	}
	// modulus for overflow: drop high-order digits beyond intDigits
	pow10 := int64(1)
	for i := 0; i < intDigits; i++ {
		pow10 *= 10
	}
	intPart = intPart % pow10

	// Build integer digits zero-padded to intDigits
	intStr := fmt.Sprintf("%0*d", intDigits, intPart)

	// Build decimal part
	decStr := ""
	if scale > 0 {
		// fractional = |v - intPartOriginalTruncated| but easier from cents
		// Get fractional as integer
		shifted := v.Shift(scale).Truncate(0)
		// fractional = shifted mod 10^scale
		p10 := int64(1)
		for i := int32(0); i < scale; i++ {
			p10 *= 10
		}
		f := shifted.IntPart() % p10
		if f < 0 {
			f = -f
		}
		decStr = fmt.Sprintf("%0*d", p10/10*0+scale, f) // simpler
		decStr = fmt.Sprintf("%0*d", scale, f)
	}

	// Map intStr onto pic pattern for integer part
	// pic intPartPic includes commas
	// We fill from rightmost digit position
	// Create slice for result of len(pic)
	res := []rune(pic)
	// First, place digits into Z/9 positions from right to left
	digitIdx := len(intStr) - 1
	for i := len(intPartPic) - 1; i >= 0; i-- {
		ch := intPartPic[i]
		if ch == 'Z' || ch == '9' {
			if digitIdx >= 0 {
				res[i] = rune(intStr[digitIdx])
				digitIdx--
			} else {
				res[i] = '0'
			}
		} else {
			// comma
			// keep as is for now
		}
	}
	// Now apply Z suppression: leading zeros in the integer part become spaces,
	// and commas within the suppressed zone become spaces.
	// Find last suppressed position: we suppress from left until we encounter
	// a non-zero digit, but we never suppress the rightmost '9' position.
	// Determine index of last '9' in intPartPic (the mandatory digit)
	lastNine := -1
	for i, ch := range intPartPic {
		if ch == '9' {
			lastNine = i
		}
	}
	suppress := true
	for i := 0; i < len(intPartPic); i++ {
		ch := intPartPic[i]
		if ch == ',' {
			continue
		}
		if i == lastNine {
			suppress = false
			break
		}
		if res[i] != '0' {
			suppress = false
			break
		}
	}
	if suppress {
		// Actually if we broke because we hit lastNine, we need to still suppress up to before it
	}
	// Apply suppression
	isSuppressedZone := true
	for i := 0; i < len(intPartPic); i++ {
		if !isSuppressedZone {
			break
		}
		ch := intPartPic[i]
		if ch == 'Z' || ch == ',' {
			if ch == 'Z' {
				if res[i] == '0' {
					// check if there is any non-zero digit to the right (up to lastNine inclusive)
					// If all remaining digits up to lastNine are zero, we still need to keep suppression?
					// Look ahead for non-zero
					hasNonZero := false
					for k := i + 1; k < len(intPartPic); k++ {
						pch := intPartPic[k]
						if pch == 'Z' || pch == '9' {
							if res[k] != '0' {
								hasNonZero = true
								break
							}
						}
					}
					if hasNonZero {
						res[i] = ' '
					} else {
						// This is leading zero before the final zero, keep as space unless it's the lastNine
						// But if i is before lastNine and all zeros, we want spaces for Z's
						res[i] = ' '
					}
				} else {
					isSuppressedZone = false
				}
			} else { // comma
				// Determine if comma is inside suppressed zone: if all digits to left are suppressed
				// Check if there is any non-zero digit to left that is not suppressed
				// Simpler: if we are still in suppression zone, comma becomes space
				// We need to know if suppression continues beyond this comma
				// Look ahead: if any non-zero digit exists after this position, then
				// the decision depends on whether left part had non-zero
				// Actually easier: after processing Z's we know isSuppressedZone still true,
				// so comma in that zone becomes space.
				res[i] = ' '
			}
		} else if ch == '9' {
			// mandatory digit; stop suppression
			isSuppressedZone = false
		}
	}
	// Build final string
	intFormatted := string(res)
	if scale > 0 {
		return intFormatted + "." + decStr
	}
	return intFormatted
