var WsTotalNet decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsPriceEd string
var WsDiscEd string
var WsNetEd string
var WsTotalEd string

var discFile *os.File
var discReader *bufio.Reader
var discRec DiscRec
var inputDone bool

func truncateDecimal(v decimal.Decimal, scale int32) decimal.Decimal {
	return v.Truncate(scale)
}

func storePic9v99(v decimal.Decimal) decimal.Decimal {
	v = truncateDecimal(v, 2)
	cents := v.Shift(2).Truncate(0)
	m := int64(10000000)
	ci := cents.IntPart()
	ci = ci % m
	if ci < 0 {
		ci += m
	}
	return decimal.New(ci, -2)
}

func storePic9v99_8(v decimal.Decimal) decimal.Decimal {
	v = truncateDecimal(v, 2)
	cents := v.Shift(2).Truncate(0)
	m := int64(10000000000)
	ci := cents.IntPart()
	ci = ci % m
	if ci < 0 {
		ci += m
	}
	return decimal.New(ci, -2)
}

func formatEdited(v decimal.Decimal, pic string) string {
	// find decimal point
	dotIdx := strings.Index(pic, ".")
	var intPic, decPic string
	scale := 0
	if dotIdx != -1 {
		intPic = pic[:dotIdx]
		decPic = pic[dotIdx+1:]
		for _, ch := range decPic {
			if ch == '9' || ch == 'Z' {
				scale++
			}
		}
	} else {
		intPic = pic
	}
	// count integer digit positions
	intDigits := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	if v.IsNegative() {
		v = v.Neg()
	}
	v = v.Truncate(int32(scale))

	// integer part
	intPart := v.IntPart()
	if intPart < 0 {
		intPart = -intPart
	}
	pow10 := int64(1)
	for i := 0; i < intDigits; i++ {
		pow10 *= 10
	}
	intPart = intPart % pow10
	intStr := fmt.Sprintf("%0*d", intDigits, intPart)

	// decimal part
	decStr := ""
	if scale > 0 {
		shifted := v.Shift(int32(scale)).Truncate(0)
		p10 := int64(1)
		for i := 0; i < scale; i++ {
			p10 *= 10
		}
		f := shifted.IntPart() % p10
		if f < 0 {
			f = -f
		}
		decStr = fmt.Sprintf("%0*d", scale, f)
	}

	// build integer formatted part
	resInt := []rune(intPic)
	digitIdx := len(intStr) - 1
	for i := len(intPic) - 1; i >= 0; i-- {
		ch := intPic[i]
		if ch == 'Z' || ch == '9' {
			if digitIdx >= 0 {
				resInt[i] = rune(intStr[digitIdx])
				digitIdx--
			} else {
				resInt[i] = '0'
			}
		}
	}
	// Z suppression
	suppressed := true
	for i := 0; i < len(intPic); i++ {
		if !suppressed {
			break
		}
		ch := intPic[i]
		if ch == 'Z' || ch == ',' {
			if ch == 'Z' {
				if resInt[i] == '0' {
					resInt[i] = ' '
				} else {
					suppressed = false
				}
			} else { // comma
				if suppressed {
					resInt[i] = ' '
				}
			}
		} else if ch == '9' {
			suppressed = false
		}
	}
	// any comma that is inside suppressed leading spaces already blanked;
	// need also blank commas that precede first significant digit but were not caught because suppression ended?
	// The loop above already blanks commas while suppressed, so fine.

	if dotIdx == -1 {
		return string(resInt)
	}
	// build decimal part formatted (usually "9" only, but handle generically)
	resDec := []rune(decPic)
	dIdx := 0
	for i := 0; i < len(resDec); i++ {
		if resDec[i] == 'Z' || resDec[i] == '9' {
			if dIdx < len(decStr) {
				resDec[i] = rune(decStr[dIdx])
				dIdx++
			} else {
				resDec[i] = '0'
			}
		}
	}
	return string(resInt) + "." + string(resDec)
}

func moveToWsPriceEd(v decimal.Decimal) {
	WsPriceEd = formatEdited(v, "ZZ,ZZ9.99")
}
func moveToWsDiscEd(v decimal.Decimal) {
	WsDiscEd = formatEdited(v, "ZZ,ZZ9.99")
}
func moveToWsNetEd(v decimal.Decimal) {
	WsNetEd = formatEdited(v, "ZZ,ZZ9.99")
}
func moveToWsTotalEd(v decimal.Decimal) {
	WsTotalEd = formatEdited(v, "ZZ,ZZZ,ZZ9.99")
}

func formatPic9(n int64, digits int) string {
	s := fmt.Sprintf("%d", n)
	if len(s) > digits {
		s = s[len(s)-digits:]
	}
	if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	return s
}

func parsePrice(s string) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.Zero
	}
	n, _ := decimal.NewFromString(s)
	return n.Shift(-2)
}

func MAIN_PARA() {
	var err error
	discFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer discFile.Close()
	discReader = bufio.NewReader(discFile)
	READ_PARA()
	for !inputDone {
		PROCESS_PARA()
	}
	discFile.Close()
	SUMMARY_PARA()
}

func READ_PARA() {
	line, err := discReader.ReadString('\n')
	if err != nil && len(line) == 0 {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	line = strings.TrimRight(line, "\r\n")
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	}
	if len(line) > 15 {
		line = line[:15]
	}
	if len(line) == 0 && err != nil {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	rawItem := line[0:6]
	rawPrice := line[6:13]
	rawPct := line[13:15]
	discRec.DrItem = rawItem
	discRec.DrPrice = parsePrice(rawPrice)
	pctStr := strings.TrimSpace(rawPct)
	if pctStr == "" {
		discRec.DrPct = 0
	} else {
		var v int64
		fmt.Sscanf(pctStr, "%d", &v)
		discRec.DrPct = v
	}
}

func PROCESS_PARA() {
	prod := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct))
	quot := prod.Shift(-2)
	rounded := quot.Round(2)
	WsDiscount = storePic9v99(rounded)
	net := discRec.DrPrice.Sub(WsDiscount)
	WsNet = storePic9v99(net.Truncate(2))
	WsTotalNet = storePic9v99_8(WsTotalNet.Add(WsNet).Truncate(2))
	WsCount++
	moveToWsPriceEd(discRec.DrPrice)
	moveToWsDiscEd(WsDiscount)
	moveToWsNetEd(WsNet)
	pctFormatted := formatPic9(discRec.DrPct, 2)
	fmt.Printf("%s %s %s%% %s %s\n", discRec.DrItem, WsPriceEd, pctFormatted, WsDiscEd, WsNetEd)
	READ_PARA_NEXT()
}

func READ_PARA_NEXT() {
	line, err := discReader.ReadString('\n')
	if err != nil && len(line) == 0 {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	line = strings.TrimRight(line, "\r\n")
	if len(line) < 15 {
		if len(line) == 0 && err != nil {
			inputDone = true
			WsEofFlag = "Y"
			return
		}
		line = line + strings.Repeat(" ", 15-len(line))
	}
	if len(line) > 15 {
		line = line[:15]
	}
	rawItem := line[0:6]
	rawPrice := line[6:13]
	rawPct := line[13:15]
	discRec.DrItem = rawItem
	discRec.DrPrice = parsePrice(rawPrice)
	pctStr := strings.TrimSpace(rawPct)
	if pctStr == "" {
		discRec.DrPct = 0
	} else {
		var v int64
		fmt.Sscanf(pctStr, "%d", &v)
		discRec.DrPct = v
	}
}

func SUMMARY_PARA() {
	moveToWsTotalEd(WsTotalNet)
	countFormatted := formatPic9(WsCount, 3)
	fmt.Printf("ITEMS: %s NET TOTAL: %s\n", countFormatted, WsTotalEd)
}

func main() {
	MAIN_PARA()
}
